{"command":"cat <<'EOF' > src/main.rs
mod languages;

use languages::{LANGUAGES, LanguageConfig};
use std::collections::{BTreeMap, HashMap};
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};
use std::env;

#[derive(Default, Clone, Debug)]
struct Stats {
    files: usize,
    lines: usize,
    code: usize,
    comments: usize,
    blanks: usize,
}

struct LanguageStats {
    name: String,
    stats: Stats,
    file_stats: Vec<(String, Stats)>,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut inputs = Vec::new();
    let mut show_files = false;
    let mut sort_by = "language".to_string();
    let mut rsort = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-f" | "--files" => show_files = true,
            "-s" | "--sort" => {
                if i + 1 < args.len() {
                    sort_by = args[i+1].clone();
                    i += 1;
                }
            }
            "-r" | "--rsort" => {
                if i + 1 < args.len() {
                    sort_by = args[i+1].clone();
                    rsort = true;
                    i += 1;
                }
            }
            "-V" | "--version" => {
                println!("tokei 14.0.0 compiled with serialization support: json");
                return;
            }
            "-h" | "--help" => {
                // ... print help ...
                return;
            }
            arg if arg.starts_with("-") => {
                // Ignore other flags for now
            }
            arg => {
                inputs.push(arg.to_string());
            }
        }
        i += 1;
    }

    if inputs.is_empty() {
        inputs.push(".".to_string());
    }

    let mut language_map: HashMap<String, LanguageStats> = HashMap::new();
    let mut ext_to_lang = HashMap::new();
    for (exts, config) in LANGUAGES {
        for ext in *exts {
            ext_to_lang.insert(ext.to_string(), config);
        }
    }

    for input in inputs {
        let path = Path::new(&input);
        if path.is_dir() {
            walk_dir(path, &ext_to_lang, &mut language_map);
        } else {
            process_file(path, &ext_to_lang, &mut language_map);
        }
    }

    // Sort and print
    let mut langs: Vec<_> = language_map.values().collect();
    // Default alphabetical
    langs.sort_by(|a, b| a.name.cmp(&b.name));

    if sort_by != "language" {
        langs.sort_by(|a, b| {
            let res = match sort_by.as_str() {
                "files" => a.stats.files.cmp(&b.stats.files),
                "lines" => a.stats.lines.cmp(&b.stats.lines),
                "code" => a.stats.code.cmp(&b.stats.code),
                "comments" => a.stats.comments.cmp(&b.stats.comments),
                "blanks" => a.stats.blanks.cmp(&b.stats.blanks),
                _ => a.name.cmp(&b.name),
            };
            if rsort { res } else { res.reverse() }
        });
    }

    print_table(&langs, show_files);
}

fn walk_dir(dir: &Path, ext_to_lang: &HashMap<String, &LanguageConfig>, language_map: &mut HashMap<String, LanguageStats>) {
    if let Ok(entries) = dir.read_dir() {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_dir() {
                    if path.file_name().map(|n| n == ".git").unwrap_or(false) {
                        continue;
                    }
                    walk_dir(&path, ext_to_lang, language_map);
                } else {
                    process_file(&path, ext_to_lang, language_map);
                }
            }
        }
    }
}

fn process_file(path: &Path, ext_to_lang: &HashMap<String, &LanguageConfig>, language_map: &mut HashMap<String, LanguageStats>) {
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
    if let Some(config) = ext_to_lang.get(ext) {
        if let Ok(stats) = count_lines(path, config) {
            let entry = language_map.entry(config.name.to_string()).or_insert_with(|| LanguageStats {
                name: config.name.to_string(),
                stats: Stats::default(),
                file_stats: Vec::new(),
            });
            entry.stats.files += 1;
            entry.stats.lines += stats.lines;
            entry.stats.code += stats.code;
            entry.stats.comments += stats.comments;
            entry.stats.blanks += stats.blanks;
            entry.file_stats.push((path.to_string_lossy().to_string(), stats));
        }
    }
}

fn count_lines(path: &Path, config: &LanguageConfig) -> std::io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut stats = Stats::default();

    let mut in_block: Option<usize> = None; // Index of current block comment style

    for line in reader.lines() {
        let line = line?;
        stats.lines += 1;
        let trimmed = line.trim();
        if trimmed.is_empty() {
            stats.blanks += 1;
            continue;
        }

        // Simplified logic for now
        let mut has_code = false;
        let mut has_comment = false;

        // This is a VERY simplified version of comment counting
        // In a real implementation we need to handle strings, nested comments, etc.
        // For now let's just do basic line comments and block comments

        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();
        let mut is_in_string = false;

        // ... (Implement more robust counting here) ...
        // For now, let's just use a simple heuristic to see if it works.
        if config.line_comments.iter().any(|c| trimmed.starts_with(c)) {
            has_comment = true;
        } else {
            has_code = true;
        }

        if has_code {
            stats.code += 1;
        } else if has_comment {
            stats.comments += 1;
        }
    }
    Ok(stats)
}

fn print_table(langs: &[&LanguageStats], _show_files: bool) {
    let width = 80;
    println!("{}", "━".repeat(width + 1));
    println!(" Language              Files        Lines         Code     Comments       Blanks");
    println!("{}", "━".repeat(width + 1));

    let mut total = Stats::default();
    for lang in langs {
        println!(" {:<20} {:>12} {:>12} {:>12} {:>12} {:>12}",
            lang.name, lang.stats.files, lang.stats.lines, lang.stats.code, lang.stats.comments, lang.stats.blanks);
        total.files += lang.stats.files;
        total.lines += lang.stats.lines;
        total.code += lang.stats.code;
        total.comments += lang.stats.comments;
        total.blanks += lang.stats.blanks;
    }

    println!("{}", "━".repeat(width + 1));
    println!(" {:<20} {:>12} {:>12} {:>12} {:>12} {:>12}",
        "Total", total.files, total.lines, total.code, total.comments, total.blanks);
    println!("{}", "━".repeat(width + 1));
}
EOF
"}

