                stats.blanks, stats.code, stats.comments, name.replace("\\", "/"));
        }
        print!("]");
    }
    print!("}},\"inaccurate\":false}}}}");
    println!();
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [input]...");
}
