    if let Some(config) = ext_to_lang.get(ext) {
        if let Ok(stats) = count_lines(path, config) {
            let entry = language_map.entry(config.name.to_string()).or_insert_with(|| LanguageStats {
                name: config.name.to_string(),
                stats: Stats::default(),
                files: 0,
                file_stats: Vec::new(),
            });
            entry.files += 1;
            entry.stats.lines += stats.lines;
            entry.stats.code += stats.code;
            entry.stats.comments += stats.comments;
            entry.stats.blanks += stats.blanks;
            entry.file_stats.push((path.to_string_lossy().to_string(), stats));
        }
    }
}

fn count_lines(path: &Path, config: &LanguageConfig) -> std::io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut stats = Stats::default();
    let mut block_stack: Vec<usize> = Vec::new();

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => return Ok(stats),
        };
        stats.lines += 1;
        if line.trim().is_empty() {
            stats.blanks += 1;
            continue;
        }

        let mut has_code = false;
        let mut has_comment = false;
        let mut is_in_string: Option<char> = None;
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();

        while i < chars.len() {
            if let Some(quote) = is_in_string {
                has_code = true;
                if chars[i] == '\\' && i + 1 < chars.len() {
                    i += 2;
                    continue;
                }
                if chars[i] == quote {
                    is_in_string = None;
                }
                i += 1;
            } else if !block_stack.is_empty() {
                has_comment = true;
                let current_block_idx = *block_stack.last().unwrap();
                let (_, end_sym) = config.block_comments[current_block_idx];

                let mut handled = false;
                if line[i..].starts_with(end_sym) {
                    block_stack.pop();
                    i += end_sym.len();
                    handled = true;
                } else if config.nested {
                     for (idx, (start_sym, _)) in config.block_comments.iter().enumerate() {
                        if line[i..].starts_with(start_sym) {
                            block_stack.push(idx);
                            i += start_sym.len();
                            handled = true;
                            break;
                        }
                    }
                }

                if !handled {
                    i += 1;
                }
            } else {
                if chars[i].is_whitespace() {
                    i += 1;
                    continue;
                }

                let mut found = false;
                for sym in config.line_comments {
                    if line[i..].starts_with(sym) {
                        has_comment = true;
                        found = true;
                        break;
                    }
                }
                if found { break; }

                for (idx, (start_sym, _)) in config.block_comments.iter().enumerate() {
                    if line[i..].starts_with(start_sym) {
                        has_comment = true;
                        block_stack.push(idx);
                        i += start_sym.len();
                        found = true;
                        break;
                    }
                }
                if found { continue; }

                if chars[i] == '"' || chars[i] == '\'' {
                    has_code = true;
                    is_in_string = Some(chars[i]);
                    i += 1;
                    continue;
                }

                has_code = true;
                i += 1;
            }
        }

        if has_code {
            stats.code += 1;
        } else if has_comment || !block_stack.is_empty() {
            stats.comments += 1;
        } else {
            stats.blanks += 1;
        }
    }
    Ok(stats)
}

fn print_table(langs: &[&LanguageStats], show_files: bool) {
    println!("{}", "━".repeat(81));
    println!(" {:<22}{:>5}{:>13}{:>13}{:>13}{:>13}", "Language", "Files", "Lines", "Code", "Comments", "Blanks");
    println!("{}", "━".repeat(81));

    let mut total_stats = Stats::default();
    let mut total_files = 0;
    for lang in langs {
        println!(" {:<22}{:>5}{:>13}{:>13}{:>13}{:>13}",
            lang.name, lang.files, lang.stats.lines, lang.stats.code, lang.stats.comments, lang.stats.blanks);

        if show_files {
            println!("{}", "─".repeat(81));
            for (name, stats) in &lang.file_stats {
