                    name, "", stats.lines, stats.code, stats.comments, stats.blanks);
            }
            println!("{}", "─".repeat(81));
        }

        total_files += lang.files;
        total_stats.lines += lang.stats.lines;
        total_stats.code += lang.stats.code;
        total_stats.comments += lang.stats.comments;
        total_stats.blanks += lang.stats.blanks;
    }

    println!("{}", "━".repeat(81));
    println!(" {:<22}{:>5}{:>13}{:>13}{:>13}{:>13}",
        "Total", total_files, total_stats.lines, total_stats.code, total_stats.comments, total_stats.blanks);
    println!("{}", "━".repeat(81));
}

fn print_json(langs: &[&LanguageStats]) {
    print!("{{");
    let mut first_lang = true;
    let mut total_blanks = 0;
    let mut total_code = 0;
    let mut total_comments = 0;

    for lang in langs {
        if !first_lang { print!(","); }
        first_lang = false;
        print!("\"{}\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":[",
            lang.name, lang.stats.blanks, lang.stats.code, lang.stats.comments);
        let mut first_file = true;
        for (name, stats) in &lang.file_stats {
            if !first_file { print!(","); }
            first_file = false;
            print!("{{\"stats\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{}}}},\"name\":\"{}\"}}",
                stats.blanks, stats.code, stats.comments, name.replace("\\", "/"));
        }
        print!("],\"children\":{{}},\"inaccurate\":false}}");

        total_blanks += lang.stats.blanks;
        total_code += lang.stats.code;
        total_comments += lang.stats.comments;
    }

    if !first_lang { print!(","); }
    print!("\"Total\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"reports\":[],\"children\":{{",
        total_blanks, total_code, total_comments);
    let mut first_total = true;
    for lang in langs {
        if !first_total { print!(","); }
        first_total = false;
        print!("\"{}\":[", lang.name);
        let mut first_file = true;
        for (name, stats) in &lang.file_stats {
            if !first_file { print!(","); }
            first_file = false;
            print!("{{\"stats\":{{\"blanks\":{},\"code\":{},\"comments\":{},\"blobs\":{{}}}},\"name\":\"{}\"}}",
                stats.blanks, stats.code, stats.comments, name.replace("\\", "/"));
        }
        print!("]");
    }
    print!("}},\"inaccurate\":false}}}}");
    println!();
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [input]...");
}
