fn count_lines(path: &Path, config: &LanguageConfig) -> std::io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut stats = Stats::default();
    let mut block_stack: Vec<usize> = Vec::new();

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => return Ok(stats),
        };
        stats.lines += 1;
        if line.trim().is_empty() {
            stats.blanks += 1;
            continue;
        }

        let mut has_code = false;
        let mut has_comment = false;
        let mut is_in_string: Option<char> = None;
        let mut i = 0;
        let chars: Vec<char> = line.chars().collect();

        while i < chars.len() {
            if let Some(quote) = is_in_string {
                has_code = true;
                if chars[i] == '\\' && i + 1 < chars.len() {
                    i += 2;
                    continue;
                }
                if chars[i] == quote {
                    is_in_string = None;
                }
                i += 1;
            } else if !block_stack.is_empty() {
                has_comment = true;
                let current_block_idx = *block_stack.last().unwrap();
                let (_, end_sym) = config.block_comments[current_block_idx];

                let mut handled = false;
                if line[i..].starts_with(end_sym) {
                    block_stack.pop();
                    i += end_sym.len();
                    handled = true;
                } else if config.nested {
                     for (idx, (start_sym, _)) in config.block_comments.iter().enumerate() {
                        if line[i..].starts_with(start_sym) {
                            block_stack.push(idx);
                            i += start_sym.len();
                            handled = true;
                            break;
                        }
                    }
                }

                if !handled {
                    i += 1;
                }
            } else {
                if chars[i].is_whitespace() {
                    i += 1;
                    continue;
                }

                let mut found = false;
                for sym in config.line_comments {
                    if line[i..].starts_with(sym) {
                        has_comment = true;
                        found = true;
                        break;
                    }
                }
                if found { break; }

                for (idx, (start_sym, _)) in config.block_comments.iter().enumerate() {
                    if line[i..].starts_with(start_sym) {
                        has_comment = true;
                        block_stack.push(idx);
                        i += start_sym.len();
                        found = true;
                        break;
                    }
                }
                if found { continue; }

                if chars[i] == '"' || chars[i] == '\'' {
                    has_code = true;
                    is_in_string = Some(chars[i]);
                    i += 1;
                    continue;
                }

                has_code = true;
                i += 1;
            }
        }

        if has_code {
            stats.code += 1;
        } else if has_comment || !block_stack.is_empty() {
            stats.comments += 1;
        } else {
            stats.blanks += 1;
        }
    }
    Ok(stats)
}

fn count_markdown(path: &Path, ext_to_lang: &HashMap<String, &LanguageConfig>) -> std::io::Result<Stats> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut stats = Stats::default();
    let mut in_code_block: Option<&LanguageConfig> = None;

    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => return Ok(stats),
        };
        stats.lines += 1;
        let trimmed = line.trim();

        if trimmed.starts_with("```") {
            if in_code_block.is_some() {
                in_code_block = None;
                stats.comments += 1;
            } else {
                let lang_name = trimmed[3..].trim();
                in_code_block = ext_to_lang.get(lang_name).copied();
                stats.comments += 1;
            }
        } else if let Some(_config) = in_code_block {
            // Very simplified: just count as code for now
            stats.code += 1;
        } else {
            if trimmed.is_empty() {
                stats.blanks += 1;
            } else {
                stats.comments += 1;
            }
        }
    }
    Ok(stats)
}

